    'impermanent-loss-calculator' => 
    array (
      'tool_slug' => 'impermanent-loss-calculator',
      'h1' => 'Impermanent Loss Calculator – DeFi LP Position Analyzer',
      'title' => 'Impermanent Loss Calculator - DeFi Liquidity Pool Analysis | ToolsHub',
      'meta_description' => 'Calculate impermanent loss for DeFi liquidity pools. Compare LP value vs HODL strategy with fee compensation, weighted pools, and time period analysis.',
      'instructions' => 
      array (
        0 => 'Enter the initial and current price of Token A in the liquidity pool.',
        1 => 'Set your total LP investment amount and pool fee APR.',
        2 => 'View impermanent loss percentage, dollar impact, and fee compensation analysis.',
