    array (
      'tool_slug' => 'price-to-book-ratio-calculator',
      'h1' => 'Price to Book Ratio Calculator',
      'title' => 'Price to Book Ratio Calculator: Evaluate Asset Valuations Intelligently',
      'meta_description' => 'Strictly calculate and extensively analyze your stock’s Price-to-Book (P/B) ratio accurately. Compare total market cap forcefully to baseline accounting asset values directly to discover hidden investments.',
      'canonical' => '/price-to-book-ratio-calculator',
      'instructions' => 
